namespace sv_45c50726043844e5b9adb3b0a25c8623.Services;

public class WarehouseStateService
{
    private string _selectedWarehouseId = "WH-001";

    public string SelectedWarehouseId
    {
        get => _selectedWarehouseId;
        set
        {
            if (_selectedWarehouseId == value) return;
            _selectedWarehouseId = value;
            NotifyStateChanged();
        }
    }

    public string SelectedWarehouseName =>
        Warehouses.TryGetValue(_selectedWarehouseId, out var name) ? name : _selectedWarehouseId;

    public static IReadOnlyDictionary<string, string> Warehouses { get; } =
        new Dictionary<string, string>
        {
            ["WH-001"] = "Warehouse A - Downtown",
            ["WH-002"] = "Warehouse B - Airport",
            ["WH-003"] = "Warehouse C - Harbor",
            ["WH-004"] = "Warehouse D - Industrial Park"
        };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

namespace sv_45c50726043844e5b9adb3b0a25c8623.Services;

public class InventoryAlertService
{
    private readonly Random _random = new();

    public int LastKnownCount { get; private set; }

    /// <summary>
    /// Simulates a database query returning low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        LastKnownCount = count;
        NotifyAlertDataChanged();
        return Task.FromResult(count);
    }

    /// <summary>
    /// Raised whenever new alert data arrives, so all subscribed components refresh.
    /// </summary>
    public event Action? OnAlertDataChanged;

    private void NotifyAlertDataChanged() => OnAlertDataChanged?.Invoke();
}

