@using sv_45c50726043844e5b9adb3b0a25c8623.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@implements IDisposable

<div class="warehouse-selector d-flex align-items-center gap-2">
    <label class="text-white mb-0 small" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="max-width: 220px;"
            value="@WarehouseState.SelectedWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseStateService.Warehouses)
        {
            <option value="@wh.Key">@wh.Value</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SelectedWarehouseId = newId;
        }
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChanged;
    }
}

@using sv_45c50726043844e5b9adb3b0a25c8623.Services
@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable

<span class="alert-badge position-relative">
    @if (AlertService.LastKnownCount > 0)
    {
        <span class="badge bg-danger rounded-pill">@AlertService.LastKnownCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertDataChanged += OnAlertDataChanged;
        WarehouseState.OnChange += OnWarehouseChanged;
    }

    private void OnAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private async void OnWarehouseChanged()
    {
        // Re-fetch alerts for the newly selected warehouse
        await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
        WarehouseState.OnChange -= OnWarehouseChanged;
    }
}

