@using sv_45c50726043844e5b9adb3b0a25c8623.Services
@rendermode InteractiveServer
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>Current Site:</strong> @WarehouseState.SelectedWarehouseName
    </div>
    <div class="card-body">
        <p>Warehouse ID: <code>@WarehouseState.SelectedWarehouseId</code></p>
    </div>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card text-bg-@(alertCount > 5 ? "danger" : alertCount > 0 ? "warning" : "success") mb-3">
            <div class="card-header">Low-Stock Alerts</div>
            <div class="card-body">
                <h2 class="card-title display-4">@alertCount</h2>
                <p class="card-text">items below minimum stock level</p>
                <small class="opacity-75">Refreshes every 10 seconds</small>
            </div>
        </div>
    </div>
    <div class="col-md-8">
        <div class="card mb-3">
            <div class="card-header">Activity Log</div>
            <div class="card-body">
                <ul class="list-group list-group-flush" style="max-height: 300px; overflow-y: auto;">
                    @foreach (var entry in pollLog.TakeLast(10).Reverse())
                    {
                        <li class="list-group-item d-flex justify-content-between">
                            <span>Polled @entry.WarehouseName</span>
                            <span class="badge bg-secondary">@entry.Count alerts @ @entry.Timestamp.ToString("HH:mm:ss")</span>
                        </li>
                    }
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private int alertCount;
    private Timer? pollingTimer;
    private readonly List<PollEntry> pollLog = new();

    protected override async Task OnInitializedAsync()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertDataChanged += OnAlertDataChanged;

        // Initial fetch
        await FetchAlerts();

        // Start polling every 10 seconds
        pollingTimer = new Timer(async _ => await PollAlerts(), null, TimeSpan.FromSeconds(10), TimeSpan.FromSeconds(10));
    }

    private async Task PollAlerts()
    {
        await FetchAlerts();
        await InvokeAsync(StateHasChanged);
    }

    private async Task FetchAlerts()
    {
        alertCount = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        pollLog.Add(new PollEntry(WarehouseState.SelectedWarehouseName, alertCount, DateTime.Now));
    }

    private async void OnWarehouseChanged()
    {
        await FetchAlerts();
        await InvokeAsync(StateHasChanged);
    }

    private void OnAlertDataChanged()
    {
        alertCount = AlertService.LastKnownCount;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        pollingTimer?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertDataChanged -= OnAlertDataChanged;
    }

    private record PollEntry(string WarehouseName, int Count, DateTime Timestamp);
}

